package com.example.domain.model.i18n

internal object DuaTh1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("เมื่อตื่นนอน", "มวลการสรรเสริญเป็นของอัลลอฮ์ผู้ทรงให้เรามีชีวิตอีกครั้งหลังจากที่ทรงให้เราตาย (หลับ) และการกลับคืนนั้นมีแด่พระองค์", "อ่านทันทีหลังตื่นนอนเพื่อขอบคุณอัลลอฮ์", "ท่านนบี ﷺ กล่าวดุอาอ์นี้เมื่อตื่นนอน — เริ่มต้นวันด้วยความขอบคุณและการรำลึกถึงวันปรโลก"),
        "dua_leaving_home" to DuaText("เมื่อออกจากบ้าน", "ด้วยพระนามของอัลลอฮ์ ข้าพระองค์มอบหมายต่ออัลลอฮ์ ไม่มีพลังและอำนาจใดนอกจากด้วยอัลลอฮ์", "อ่านเมื่อออกจากบ้านเพื่อขอความคุ้มครอง", "ผู้ที่อ่านดุอาอ์นี้จะได้รับคำกล่าวว่า ท่านได้รับการชี้นำ ได้รับความเพียงพอ และได้รับการคุ้มครองแล้ว และชัยฏอนจะหลีกห่างจากเขา"),
        "dua_anxiety_distress" to DuaText("ดุอาอ์เมื่อกังวลและเศร้าโศก", "โอ้อัลลอฮ์ ข้าพระองค์ขอความคุ้มครองต่อพระองค์ให้พ้นจากความกังวลและความเศร้าโศก จากความอ่อนแอและความเกียจคร้าน จากความตระหนี่และความขี้ขลาด จากภาระหนี้สินและการกดขี่ของผู้คน", "ในยามกังวล เศร้าโศก มีหนี้สิน และทุกข์ใจ", "ท่านนบี ﷺ มักกล่าวดุอาอ์นี้เพื่อขอความคุ้มครองจากความเศร้าโศก ความเกียจคร้าน และหนี้สิน"),
        "dua_sayyidul_istighfar" to DuaText("ประมุขแห่งการขออภัยโทษ (ซัยยิดุลอิสติฆฟาร)", "โอ้อัลลอฮ์ พระองค์คือพระเจ้าของข้าพระองค์ ไม่มีพระเจ้าอื่นใดนอกจากพระองค์ พระองค์ทรงสร้างข้าพระองค์ และข้าพระองค์เป็นบ่าวของพระองค์ ข้าพระองค์ยึดมั่นในพันธสัญญาของพระองค์เท่าที่ข้าพระองค์สามารถทำได้ ข้าพระองค์ขอความคุ้มครองต่อพระองค์จากความชั่วที่ข้าพระองค์ได้กระทำ ข้าพระองค์ยอมรับความโปรดปรานของพระองค์ที่มีต่อข้าพระองค์ และข้าพระองค์ยอมรับบาปของข้าพระองค์ ขอพระองค์ทรงอภัยโทษแก่ข้าพระองค์ด้วยเถิด เพราะไม่มีผู้ใดอภัยโทษบาปได้นอกจากพระองค์", "อ่านในตอนเช้าและตอนเย็น — ดุอาอ์ขออภัยโทษที่ประเสริฐที่สุดที่ท่านนบี ﷺ สอนไว้", "ผู้ที่อ่านในตอนเย็นด้วยความเชื่อมั่นแล้วเสียชีวิตในคืนนั้นจะเข้าสวรรค์ เช่นเดียวกับผู้ที่อ่านในตอนเช้า"),
        "dua_parents" to DuaText("ดุอาอ์เพื่อบิดามารดา", "ข้าแต่พระผู้อภิบาลของข้าพระองค์ ขอทรงเมตตาต่อท่านทั้งสองดังที่ท่านทั้งสองได้เลี้ยงดูข้าพระองค์มาตั้งแต่เล็ก", "ดุอาอ์จากอัลกุรอานเพื่อตอบแทนการเลี้ยงดูของบิดามารดา", "อัลลอฮ์ทรงบัญชาดุอาอ์นี้สำหรับบิดามารดาไว้โดยตรงในอัลกุรอาน"),
        "dua_entering_mosque" to DuaText("เมื่อเข้ามัสยิด", "โอ้อัลลอฮ์ ขอทรงเปิดประตูแห่งความเมตตาของพระองค์แก่ข้าพระองค์", "อ่านเมื่อเข้ามัสยิดด้วยเท้าขวา", "ท่านนบี ﷺ สอนดุอาอ์นี้สำหรับการเข้ามัสยิด"),
        "dua_morning_asbahna" to DuaText("การรำลึกยามเช้า", "เราได้เข้าสู่ยามเช้าและอำนาจการปกครองเป็นของอัลลอฮ์ มวลการสรรเสริญเป็นของอัลลอฮ์ ไม่มีพระเจ้าอื่นใดนอกจากอัลลอฮ์องค์เดียว ไม่มีภาคี อำนาจเป็นของพระองค์ การสรรเสริญเป็นของพระองค์ และพระองค์ทรงอานุภาพเหนือทุกสิ่ง", "การรำลึกที่แนะนำให้อ่านในยามเช้า", "เริ่มต้นวันด้วยการยอมรับอำนาจและความเป็นเอกะของอัลลอฮ์"),
        "dua_evening_amsayna" to DuaText("การรำลึกยามเย็น", "เราได้เข้าสู่ยามเย็นและอำนาจการปกครองเป็นของอัลลอฮ์ มวลการสรรเสริญเป็นของอัลลอฮ์ ไม่มีพระเจ้าอื่นใดนอกจากอัลลอฮ์องค์เดียว ไม่มีภาคี อำนาจเป็นของพระองค์ การสรรเสริญเป็นของพระองค์ และพระองค์ทรงอานุภาพเหนือทุกสิ่ง", "การรำลึกที่แนะนำให้อ่านในยามเย็น", "เริ่มต้นค่ำคืนด้วยการยอมรับอำนาจและความเป็นเอกะของอัลลอฮ์"),
        "dua_before_sleep" to DuaText("ก่อนนอน", "ด้วยพระนามของพระองค์ โอ้อัลลอฮ์ ข้าพระองค์ตายและมีชีวิต", "อ่านหลังจากนอนลงบนที่นอน", "ท่านนบี ﷺ กล่าวดุอาอ์นี้ก่อนนอน"),
        "dua_travel" to DuaText("ดุอาอ์การเดินทาง", "มหาบริสุทธิ์แด่พระผู้ทรงให้พาหนะนี้อยู่ใต้บังคับของเรา ทั้งที่เราไม่สามารถควบคุมมันได้ด้วยตัวเราเอง และแท้จริงเราจะกลับไปยังพระผู้อภิบาลของเรา", "อ่านเมื่อขึ้นพาหนะหลังจากกล่าวตักบีรสามครั้ง", "ดุอาอ์การเดินทางที่สอนไว้เพื่อความคุ้มครองและความจำเริญ"),
        "dua_ayatul_kursi" to DuaText("อายะตุลกุรซีหลังละหมาด", "อัลลอฮ์ ไม่มีพระเจ้าอื่นใดนอกจากพระองค์ ผู้ทรงมีชีวิตอยู่นิรันดร์ ผู้ทรงบริหารทุกสิ่ง ไม่มีอาการง่วงและการหลับใดๆ มาครอบงำพระองค์ได้ สิ่งที่อยู่ในชั้นฟ้าและแผ่นดินเป็นของพระองค์ ผู้ใดเล่าจะขอความช่วยเหลือ ณ ที่พระองค์โดยปราศจากอนุมัติของพระองค์ พระองค์ทรงรอบรู้สิ่งที่อยู่เบื้องหน้าและเบื้องหลังของพวกเขา และพวกเขาไม่อาจครอบคลุมความรู้ของพระองค์ได้เว้นแต่สิ่งที่พระองค์ทรงประสงค์ บัลลังก์ของพระองค์กว้างขวางครอบคลุมชั้นฟ้าและแผ่นดิน การรักษาทั้งสองมิได้เป็นภาระแก่พระองค์ และพระองค์คือผู้ทรงสูงส่ง ผู้ทรงยิ่งใหญ่", "อ่านหลังละหมาดฟัรฎูทุกครั้งและก่อนนอน", "ผู้ที่อ่านหลังละหมาดฟัรฎูทุกครั้งจะไม่มีสิ่งใดขวางกั้นเขาจากการเข้าสวรรค์นอกจากความตาย ผู้ที่อ่านก่อนนอนจะได้รับการคุ้มครองจนถึงเช้า"),
        "dua_hasbunallah" to DuaText("อัลลอฮ์ทรงเพียงพอแก่เรา", "อัลลอฮ์ทรงเพียงพอแก่เรา และพระองค์คือผู้พิทักษ์ที่ดีที่สุด", "อ่านเมื่อกลัวศัตรูหรืออันตรายใหญ่หลวง", "อิบรอฮีมกล่าวคำนี้เมื่อถูกโยนเข้ากองไฟ และท่านนบี ﷺ กล่าวในยามอันตราย"),
        "dua_entering_home" to DuaText("เมื่อเข้าบ้าน", "ด้วยพระนามของอัลลอฮ์เราได้เข้ามา ด้วยพระนามของอัลลอฮ์เราได้ออกไป และเราขอมอบหมายต่อพระผู้อภิบาลของเราคืออัลลอฮ์", "อ่านเมื่อเข้าบ้านพร้อมกล่าวพระนามอัลลอฮ์และให้สลาม", "ผู้ที่รำลึกถึงอัลลอฮ์เมื่อเข้าบ้านและเมื่อรับประทานอาหาร ชัยฏอนจะกล่าวว่า ไม่มีที่พักและอาหารเย็นสำหรับพวกเจ้า"),
        "dua_yunus" to DuaText("ดุอาอ์ของท่านนบียูนุส (ศานติจงมีแด่ท่าน)", "ไม่มีพระเจ้าอื่นใดนอกจากพระองค์ มหาบริสุทธิ์แด่พระองค์ แท้จริงข้าพระองค์เป็นหนึ่งในผู้อธรรม", "ดุอาอ์ของท่านนบียูนุสในท้องปลา — สำหรับความยากลำบากทุกประการ", "ไม่มีมุสลิมคนใดวิงวอนด้วยดุอาอ์นี้ในเรื่องใดเว้นแต่อัลลอฮ์จะทรงตอบรับ"),
        "dua_karb" to DuaText("ดุอาอ์เมื่อทุกข์ยากรุนแรง", "ไม่มีพระเจ้าอื่นใดนอกจากอัลลอฮ์ผู้ทรงยิ่งใหญ่ ผู้ทรงหนักแน่น ไม่มีพระเจ้าอื่นใดนอกจากอัลลอฮ์ พระผู้อภิบาลแห่งบัลลังก์อันยิ่งใหญ่ ไม่มีพระเจ้าอื่นใดนอกจากอัลลอฮ์ พระผู้อภิบาลแห่งชั้นฟ้า แผ่นดิน และบัลลังก์อันทรงเกียรติ", "อ่านในยามทุกข์ยากและคับขันรุนแรง", "ท่านนบี ﷺ กล่าวดุอาอ์นี้ในยามทุกข์ยาก"),
    )
}
